  const act=aS/n,inh=iS/n,crc=cr/n;
  const bg=(Math.sin(wx*0.04+wy*0.025+t*0.8)+Math.sin(wx*0.03-wy*0.04+t*1.1))/2+Math.sin((wx+wy)*0.12+t*2.5)*0.2+Math.sin((wx-wy)*0.1-t*2)*0.2+Math.sin(wx*0.08-t*1.5)*Math.cos(wy*0.06+t*1.2)*0.15;
